// Read the delayed sample
readPosition = writePosition - delaySamples;
if (readPosition < 0) readPosition += MAX_DELAY_SAMPLES;
delayed = delayBuffer[readPosition];

// Write input plus feedback
delayBuffer[writePosition] = input + feedbackSource * feedback;

// Mix and advance
output = input * (1 - mix) + delayed * mix;
writePosition = (writePosition + 1) % MAX_DELAY_SAMPLES;

// Left feeds back into itself
leftBuffer[writePos] = leftIn + leftBuffer[readPos] * feedback;

// Right feeds back from the left line when ping-pong is on
source = pingPong ? leftBuffer[readPos] : rightBuffer[readPos];
rightBuffer[writePos] = rightIn + source * feedback;
